# Formula: (r, c) → (15-c, 15-r)

def is_symmetric():
    for r in range(16):
        for c in range(16):
            val = grid[r][c]
            if val != 0:
                r2, c2 = 15-c, 15-r
                val2 = grid[r2][c2]
                if val != val2:
                    print(f"NOT SYMMETRIC: ({r},{c})={val} but ({r2},{c2})={val2}")
                    return False
    return True

print("Is grid symmetric across anti-diagonal?", is_symmetric())

if is_symmetric():
    print("\nPattern is already symmetric! Output should be same as input.")

